// --- CONFIGURAZIONE ---
u_min := 0;
u_max := 6.28318; // 2*PI
v_min := 0;
v_max := 6.28318;
steps := 350;

// --- CODICE SHADER ---
// NB: non dichiarare variabili chiamate PI, pi, tau: il traduttore
// le sostituisce col valore numerico in tutto lo script.

// Parametri Geometrici
float a = 3.0; // Ampiezza della lemniscata
float r = 0.5; // Raggio del tubo

// Curva: lemniscata di Gerono nel piano z=0.
// Passa DUE volte per l'origine (u = 0 ed u = 3.14159): li' il tubo
// si autointerseca.
vec3 Curve = vec3(
    a * sin(u),
    a * sin(u) * cos(u),
    0.0
);

// --- DERIVATA PRIMA (Velocita' Analitica) ---
vec3 dC = vec3(
    a * cos(u),
    a * cos(2.0 * u),
    0.0
);

vec3 Tangent = normalize(dC);

// --- CALCOLO FRAME STABILE ---
// La curva sta nel piano z=0: la tangente non risulta mai
// parallela a Z, quindi il frame non degenera mai.
vec3 Up = vec3(0.0, 0.0, 1.0);
vec3 Binorm = normalize(cross(Tangent, Up));
vec3 Norm = normalize(cross(Binorm, Tangent));

// --- COSTRUZIONE TUBO ---
vec3 pos = Curve + r * (cos(v) * Norm + sin(v) * Binorm);

// Ritorno del punto in 4D (X, Y, Z, P)
return vec4(pos * 0.35, 0.0);

//CUTOUT_BEGIN
// Taglio delle pareti interne nel punto di autointersezione.
//
// ERRORE della versione precedente: assumevo che l'incrocio in u=0 si
// risolvesse confrontando col punto "specchiato" u_mirror = -u sullo STESSO
// nodo. E' FALSO: i due bracci che si toccano in u=0 sono quello che ESCE
// da u=0 (verso il primo quadrante) e quello che ARRIVA a u=3.14159 (dal
// quarto quadrante) -- sono vicini nello SPAZIO 3D ma lontanissimi nel
// parametro u. Il punto specchiato -u era quasi sempre troppo lontano nello
// spazio 3D per essere utile: il test non scattava quasi mai, lasciando
// lembi di parete interna intatti (visibili come cresta residua).
//
// FIX: quando u e' vicino a un nodo (0 o 3.14159), cerchiamo il vero minimo
// di distanza campionando ATTORNO A ENTRAMBI i nodi (non solo quello piu'
// vicino a u), escludendo solo il proprio intorno immediato. Verificato
// numericamente: il test e' simmetrico (se un punto del ramo A risulta
// dentro il ramo B, il punto REALMENTE sovrapposto sul ramo B viene
// anch'esso tagliato) e resta confinato alla zona vera dell'incrocio (zero
// tagli lontano dai nodi).
float a2 = 3.0;
float r2 = 0.5;
float PI_2 = 3.14159265359;

// Attivazione: il test si avvia solo se u e' vicino a un nodo (altrimenti
// costo sprecato lontano dall'incrocio).
float activateWindow = 0.5;
float dNode0 = min(abs(u), PI_2 * 2.0 - abs(u));
float dNodePi = abs(u - PI_2);
bool nearNode = (dNode0 < activateWindow) || (dNodePi < activateWindow);

bool didCut = false;

if (nearNode) {
    vec3 Curve2 = vec3(
        a2 * sin(u),
        a2 * sin(u) * cos(u),
        0.0
    );
    vec3 dC2 = vec3(
        a2 * cos(u),
        a2 * cos(2.0 * u),
        0.0
    );
    vec3 Tangent2 = normalize(dC2);
    vec3 Up2 = vec3(0.0, 0.0, 1.0);
    vec3 Binorm2 = normalize(cross(Tangent2, Up2));
    vec3 Norm2 = normalize(cross(Binorm2, Tangent2));
    vec3 pos2 = Curve2 + r2 * (cos(v) * Norm2 + sin(v) * Binorm2);

    // 2026-07-21: le toppe chiaro/scuro e i bordi frastagliati alla
    // giuntura erano RUMORE DI CAMPIONAMENTO: 24 campioni su una
    // finestra di 1.0 rad stimano il minimo con errore fino a ~0.008
    // (quasi il 2% di r2), quindi lungo la cucitura il test teneva o
    // tagliava frammenti a caso: i lembi tenuti per errore coincidono
    // in profondita' con l'altro ramo (z-fight -> toppe) e il bordo
    // del taglio ondeggia (frastagliato). Fix in due mosse:
    // 1) si cerca solo attorno al nodo dell'ALTRO ramo: u e' gia'
    //    vicino a un nodo, e il ramo che puo' toccare questo punto e'
    //    sempre quello dell'altro nodo, mai il proprio (verificato
    //    numericamente: il proprio ramo resta a distanza > 0.8).
    //    Sparisce anche excludeSelf.
    // 2) scansione grossolana (24 campioni) + 5 passi di Newton sul
    //    vero minimo: errore misurato 7e-8 (prima 8e-3).
    // La soglia resta la SIMMETRICA originale (r2 su entrambi i rami):
    // con la distanza precisa non servono asimmetrie, che alle
    // tangenze (0,0,+/-r) aprivano buchi (areola rossa).
    float otherNode = (dNode0 < dNodePi) ? PI_2 : 0.0;

    float bestU = otherNode;
    float bestDist = 1000.0;
    for (float k = 0.0; k < 24.0; k = k + 1.0) {
        float u2 = otherNode - 0.5 + k / 23.0;
        vec3 c2 = vec3(a2 * sin(u2), a2 * sin(u2) * cos(u2), 0.0);
        float d = length(pos2 - c2);
        if (d < bestDist) { bestDist = d; bestU = u2; }
    }

    // Newton su g(u2) = dot(pos2 - C(u2), C'(u2)) = 0
    float uN = bestU;
    for (float it = 0.0; it < 5.0; it = it + 1.0) {
        vec3 cN = vec3(a2 * sin(uN), a2 * sin(uN) * cos(uN), 0.0);
        vec3 t1 = vec3(a2 * cos(uN), a2 * cos(2.0 * uN), 0.0);
        vec3 t2 = vec3(-a2 * sin(uN), -2.0 * a2 * sin(2.0 * uN), 0.0);
        vec3 w = pos2 - cN;
        float g = dot(w, t1);
        float gp = dot(w, t2) - dot(t1, t1);
        if (abs(gp) > 0.000001) { uN = uN - g / gp; }
        uN = clamp(uN, otherNode - 0.55, otherNode + 0.55);
    }
    vec3 cB = vec3(a2 * sin(uN), a2 * sin(uN) * cos(uN), 0.0);
    bestDist = min(bestDist, length(pos2 - cB));

    didCut = (bestDist < r2);
}

return didCut;
//CUTOUT_END

